// TODO: Implement actual file copy from source to local BCP storage
// Copy from source_file_path to:
//   /data/pdfs/{tenant_id}/{mrn}/{document_type}/{document_name}

const tenantId = $env.DEFAULT_TENANT_ID || 'DEFAULT';
const mrn = $input.item.json.mrn;
const docType = $input.item.json.document_type;
const docName = $input.item.json.document_name;

const localPath = `/data/pdfs/${tenantId}/${mrn}/${docType}/${docName}`;

// In production, copy the file here using fs or an HTTP download
// For now, pass through the metadata

return {
  json: {
    ...$input.item.json,
    local_file_path: localPath
  }
};
